import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Error Boundaries', () => {
  test('Renders the crash button initially', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#crash-btn');
if (!btn) throw new Error('No button with id "crash-btn" found');
const fallback = root.querySelector('#error-fallback');
if (fallback) throw new Error('Fallback should not render before the error');
  });

  test('Boundary shows fallback when child crashes', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#crash-btn');
const origError = console.error;
console.error = () => {};
try {
  btn.click();
  await tick();
  await tick();
} finally {
  console.error = origError;
}
const fallback = root.querySelector('#error-fallback');
if (!fallback) throw new Error('Expected fallback with id "error-fallback" after the crash');
if (!fallback.textContent.includes('Something went wrong'))
  throw new Error('Fallback should say "Something went wrong"');
  });
});
